// src/api/itemAPI.js
import axios_api from "./axios";
import { apiPath } from "./config";

const host = apiPath("/plan/itemlist");

// 전체 조회
export const getItemList = async () => {
  const res = await axios_api.get(host);
  return res.data;
};

// 등록
export const createItemList = async (formData) => {
  const payload = {
    itemCode: String(formData.itemCode || "").trim(),
    itemName: String(formData.itemName || "").trim(),
    itemPrice: Number(formData.itemPrice ?? 0),
    itemSpec: String(formData.itemSpec ?? ""),
  };
  const res = await axios_api.post(host, payload);
  return res.data;
};

// 수정
export const updateItemList = async (formData) => {
  const { itemNo, itemCode, itemName, itemPrice, itemSpec } = formData;
  if (!itemNo) throw new Error("itemNo 누락");

  const payload = {
    itemCode: String(itemCode || "").trim(),
    itemName: String(itemName || "").trim(),
    itemPrice: Number(itemPrice ?? 0),
    itemSpec: String(itemSpec ?? ""),
  };
  const res = await axios_api.put(apiPath(`/plan/itemlist/${itemNo}`), payload);
  return res.data;
};

// 삭제
export const deleteItemList = async (itemNo) => {
  const res = await axios_api.delete(apiPath(`/plan/itemlist/${itemNo}`));
  return res.data;
};
